import{_ as n,o as r,c as t,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/gp-platzhalter-ersetzen.jpg",g=JSON.parse('{"title":"Nicht ersetzte Platzhalter in Bemerkungen auflösen","description":"","frontmatter":{"title":"Nicht ersetzte Platzhalter in Bemerkungen auflösen","source_pageid":786,"source_revision":2579},"headers":[],"relativePath":"zeugnisse/vorbereitung/platzhalter-in-memo-feldern-ersetzen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/platzhalter-in-memo-feldern-ersetzen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),s={name:"zeugnisse/vorbereitung/platzhalter-in-memo-feldern-ersetzen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function l(o,e,p,u,z,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="nicht-ersetzte-platzhalter-in-bemerkungen-auflosen" tabindex="-1">Nicht ersetzte Platzhalter in Bemerkungen auflösen <a class="header-anchor" href="#nicht-ersetzte-platzhalter-in-bemerkungen-auflosen" aria-label="Permalink to &quot;Nicht ersetzte Platzhalter in Bemerkungen auflösen&quot;">​</a></h1><p>Ersetzen Sie verbliebene Floskelplatzhalter in mehrzeiligen Bemerkungsfeldern (Memofeldern), wenn die automatische Ersetzung nach einer Übernahme oder einem Import nicht erfolgt ist.</p><p><a href="/bilder/vorbereitung/gp-platzhalter-ersetzen.jpg"><img src="'+a+'" alt="Gruppenprozess: Platzhalter in Memo-Feldern ersetzen" loading="lazy"></a></p><p><em>Gruppenprozess: Platzhalter in Memo-Feldern ersetzen</em></p><p>Beim Anlegen und Bearbeiten von Floskeln im entsprechenden Katalog kann mit Platzhaltern gearbeitet werden (z.B. $Vorname$), die dann nach dem Eintrag bei den Schülerinnen und Schülern automatisch vom Programm ersetzt werden.</p><p>In Einzelfällen, zum Beispiel nach dem Import einer neuen Floskelliste, funktioniert diese automatische Ersetzung nicht.</p><p>Ist dies der Fall, kann sie durch den Gruppenprozess &quot;Platzhalter in Memofeldern ersetzen&quot; angestoßen werden. Dieser ist im Gruppenprozessbereich &quot;Noten, Zeugnisvorbereitung&quot; zu finden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Platzhalter_in_Memo-Feldern_ersetzen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 2579.</p>',9)])])}const d=n(s,[["render",l]]);export{g as __pageData,d as default};
